func saveToggleRoute(saved bool) string {
	if saved {
		return "/api/library/remove"
	}
	return "/api/library"
}

func saveToggleVals(row DetailRow) string {
	if row.Saved {
		return libraryArgs(row.Plugin, row.Slug, "", "")
	}
	return libraryArgs(row.Plugin, row.Slug, row.Name, detailCoverURL(row))
}

func saveToggleLabel(saved bool) string {
	if saved {
		return "★ Saved"
	}
	return "☆ Save"
}

func saveToggleTitle(saved bool) string {
	if saved {
		return "Remove from library"
	}
	return "Save to library"
}

func saveToggleClass(saved bool) string {
	if saved {
		return "rounded-md border border-amber-400 bg-amber-400/20 px-3 py-1.5 text-xs font-semibold text-amber-200 shadow-[0_0_0_1px_rgba(251,191,36,0.25)] transition hover:bg-amber-400/30"
	}
	return "rounded-md border border-zinc-700 px-3 py-1.5 text-xs font-medium text-zinc-300 transition hover:border-zinc-500 hover:text-zinc-100"
}

// detailOr returns value when non-empty, else the placeholder.
func detailOr(value, placeholder string) string {
	if value != "" {
		return value
	}
	return placeholder
}

// libraryArgs marshals the hx-vals JSON payload for the library save and
// remove endpoints; empty name and cover yield the remove payload.
func libraryArgs(plugin, slug, name, cover string) string {
	b, _ := json.Marshal(struct {
		Plugin string `json:"plugin"`
		Slug   string `json:"slug"`
		Name   string `json:"name,omitempty"`
		Cover  string `json:"cover,omitempty"`
	}{Plugin: plugin, Slug: slug, Name: name, Cover: cover})
	return string(b)
}

// detailCoverURL returns the user-chosen cover when set, else the plugin cover.
func detailCoverURL(row DetailRow) string {
	if row.ChosenCover != "" {
		return row.ChosenCover
	}
	return row.Cover
}

